// An outfit in GPU memory and its draws (avatar_runtime.h): one draw per material of each model (FORMATS.md, section
// 3.6), skinned on the GPU (section 4.4), through the shaders tools/gen_shaders.py makes.

#include <math.h>
#include <stdlib.h>
#include <string.h>

#include "avatar_internal.h"
#include "avatar_math.h"
#include "avatar_runtime.h"
#include "avatar_shaders.h" // generated by tools/gen_shaders.py
#include "xsdk/gpu.h"
#include "xsdk/log.h"
#include "xsdk/shader.h"

enum {
	// A vertex in GPU memory, in floats: position, normal, six texture coordinate pairs, four bones (each as its
	// first matrix row, the index times 3) and their four weights.
	UV_SLOTS = 6,
	POSITION_AT = 0,
	NORMAL_AT = 3,
	UVS_AT = 6,
	BONES_AT = UVS_AT + 2 * UV_SLOTS,
	WEIGHTS_AT = BONES_AT + 4,
	VERTEX_FLOATS = WEIGHTS_AT + 4,
	STRIDE_BYTES = VERTEX_FLOATS * 4,
	BONE_ELEMENTS = 5, // the vertex layout's: four bones of a float each, the weights as a float4
	MAX_PART_VERTICES = 65535, // 16-bit indices

	// The vertex shader's constants (float4 vectors): mvp, world, then the bones' skin matrices, three rows each.
	MVP_AT = 0,
	WORLD_AT = 4,
	SKIN_AT = 8,
	MATRIX_VECTORS = 3 * XSDK_AVATAR_BONES,
	VERTEX_PUSH_VECTORS = SKIN_AT + MATRIX_VECTORS,

	// The pixel shaders' constants (tools/gen_shaders.py). An item's: its three colours, then its reflection (x
	// whether it reflects, y the shine); the Head's: the skin, then each layer's three colours.
	ITEM_TEXTURES = 3, // base, mask, and decal or reflection
	ITEM_BASE = 0,
	ITEM_MASK = 1,
	ITEM_OVER = 2,
	ITEM_REFLECTION = 3,
	ITEM_CONSTANTS = 4,
	HEAD_SKIN = 0,
	HEAD_LAYER_COLORS = 1,
	HEAD_CONSTANTS = HEAD_LAYER_COLORS + 3 * AVATAR_HEAD_LAYERS, // AVATAR_DRAW_CONSTANTS
	// Then the lighting (LIGHT_MEMBERS): the light's direction and colour, the sky and the ground, the camera's
	// right, up and forward axes.
	LIGHT_VECTORS = 7,
	LIGHT_SET_VECTORS = 4, // those xsdk_avatar_set_light sets; the camera's axes follow
	ITEM_LIGHT_AT = ITEM_CONSTANTS,
	HEAD_LIGHT_AT = HEAD_CONSTANTS,

	GPU_PAGE_BYTES = 64 * 1024, // xsdk_gpu_alloc's unit
	UPLOADED_MAX = 32,          // textures a model may bind; the pack's have far fewer
	TEXTURE_ALIGN_BYTES = 4096, // xsdk_texture_attach's
	DXT_BLOCK_ROWS = 4,         // texel rows a row of DXT blocks covers
	BLANK_SIDE = 4,

	// The shadow: a quad of positions; its vertex shader takes the view-projection and where it lies (4 + 1 vectors),
	// its pixel shader its middle and radius, and its colour and strength (2).
	SHADOW_VERTICES = 6,
	SHADOW_STRIDE_BYTES = 3 * 4,
	SHADOW_VERTEX_VECTORS = 5,
	SHADOW_PIXEL_VECTORS = 2,
};

// The shadow under an avatar: a disc this wide, this dark at its middle, lifted this far above the ground so that a
// floor drawn at the same height doesn't hide it. As the store sample drew it by hand before.
static const float shadow_radius = 0.38f, shadow_strength = 0.45f, shadow_lift = 0.005f;

// What every avatar draws with, made on first use (avatar_render_open), and the light set for all of them.
static struct {
	bool opened;
	XsdkShader vertex_shader, item_shader, head_shader;
	XsdkShader shadow_vertex_shader, shadow_pixel_shader;
	volatile uint32_t *shadow_quad; // SHADOW_VERTICES positions: a unit square round the origin on the ground
	XsdkSamplerState sampler, clamp_sampler; // XSDK_AVATAR_ADDRESS_WRAP and _CLAMP (FORMATS.md, section 3.6)
	XsdkTexture blank; // transparent black: a missing mask, decal or face layer
	XsdkBlendState alpha_blend, no_blend; // see-through parts, by their alpha; and back to none after
	// The light's first constants, as the pixel shaders take them; the default's until a title sets its own.
	float light[LIGHT_SET_VECTORS][4];
	bool light_set;
} renderer;

// The light every avatar is drawn with (xsdk_avatar_set_light): from the upper left, in front, warm, with a cooler
// sky and a darker ground. Chosen by eye against the system's own render (FORMATS.md, section 5.3), not from data.
static const XsdkAvatarLight default_light = {
	.direction = { -0.45f, 0.55f, 0.70f },
	.color = { 0.80f, 0.78f, 0.74f },
	.sky = { 0.46f, 0.47f, 0.50f },
	.ground = { 0.22f, 0.20f, 0.19f },
	.wrap = 0.35f,
	.highlight = 0.0f, // the system draws avatars matte (test run 6, its Dress Up screen)
};

static void store_float(volatile uint32_t *word, float value)
{
	uint32_t bits;
	memcpy(&bits, &value, 4);
	*word = bits;
}

// The GPU memory an allocation of size_bytes takes: whole pages.
static uint32_t pages(uint32_t size_bytes)
{
	return avatar_round_up(size_bytes, GPU_PAGE_BYTES);
}

static bool load(XsdkShader *shader, const AvatarShaderCode *code)
{
	const NTSTATUS status = xsdk_shader_load(shader, code->container, code->container_bytes);
	if (!NT_SUCCESS(status))
		xsdk_log_write("avatar: shader load failed: 0x%08X", (unsigned)status);
	return NT_SUCCESS(status);
}

static NTSTATUS set_layout(void)
{
	// Locations as xost maps them: 0 position, 1 colour (our normal), 2 on texture coordinates 0 on: the six UV sets,
	// then the four bones (one float each) and the weights (a float4).
	XsdkVertexElement layout[2 + UV_SLOTS + BONE_ELEMENTS] = {
		{ .usage = XSDK_USAGE_POSITION, .format = XSDK_VERTEX_FLOAT3, .offset_bytes = 4 * POSITION_AT },
		{ .usage = XSDK_USAGE_COLOR, .format = XSDK_VERTEX_FLOAT3, .offset_bytes = 4 * NORMAL_AT },
	};
	for (uint32_t k = 0; k < UV_SLOTS; k++)
		layout[2 + k] = (XsdkVertexElement){ .usage = XSDK_USAGE_TEXCOORD,
			.usage_index = k,
			.format = XSDK_VERTEX_FLOAT2,
			.offset_bytes = 4 * (UVS_AT + 2 * k) };
	for (uint32_t k = 0; k < BONE_ELEMENTS; k++)
		layout[2 + UV_SLOTS + k] = (XsdkVertexElement){ .usage = XSDK_USAGE_TEXCOORD,
			.usage_index = UV_SLOTS + k,
			.format = k < 4 ? XSDK_VERTEX_FLOAT1 : XSDK_VERTEX_FLOAT4,
			.offset_bytes = 4 * (BONES_AT + k) };
	return xsdk_shader_set_vertex_layout(
		&renderer.vertex_shader, layout, sizeof layout / sizeof layout[0], (const uint32_t[]){ STRIDE_BYTES });
}

static void make_states(void)
{
	const XsdkSampler setting = {
		.mag_filter = XSDK_FILTER_LINEAR,
		.min_filter = XSDK_FILTER_LINEAR,
		.mip_filter = XSDK_FILTER_POINT,
		.address_u = XSDK_ADDRESS_WRAP,
		.address_v = XSDK_ADDRESS_WRAP,
	};
	xsdk_texture_sampler_state(&renderer.sampler, &setting);
	XsdkSampler clamped = setting;
	clamped.address_u = XSDK_ADDRESS_CLAMP;
	clamped.address_v = XSDK_ADDRESS_CLAMP;
	xsdk_texture_sampler_state(&renderer.clamp_sampler, &clamped);
	const XsdkBlend over = { .color_source = XSDK_BLEND_SRC_ALPHA,
		.color_dest = XSDK_BLEND_ONE_MINUS_SRC_ALPHA,
		.color_op = XSDK_BLEND_OP_ADD,
		.alpha_source = XSDK_BLEND_ONE,
		.alpha_dest = XSDK_BLEND_ZERO,
		.alpha_op = XSDK_BLEND_OP_ADD,
		.write_mask = XSDK_WRITE_ALL };
	const XsdkBlend none = { .color_source = XSDK_BLEND_ONE,
		.color_dest = XSDK_BLEND_ZERO,
		.color_op = XSDK_BLEND_OP_ADD,
		.alpha_source = XSDK_BLEND_ONE,
		.alpha_dest = XSDK_BLEND_ZERO,
		.alpha_op = XSDK_BLEND_OP_ADD,
		.write_mask = XSDK_WRITE_ALL };
	xsdk_gpu_blend_state(&renderer.alpha_blend, &over);
	xsdk_gpu_blend_state(&renderer.no_blend, &none);
}

// The blank texture: transparent black, in GPU memory.
static NTSTATUS make_blank(void)
{
	const NTSTATUS status =
		xsdk_texture_create(&renderer.blank, XSDK_FORMAT_A8R8G8B8, BLANK_SIDE, BLANK_SIDE, 1, false);
	if (!NT_SUCCESS(status))
		return status;
	static const uint32_t zeros[BLANK_SIDE * BLANK_SIDE] = { 0 };
	xsdk_texture_upload(&renderer.blank, 0, zeros, BLANK_SIDE * 4);
	xsdk_gpu_invalidate(renderer.blank.address, renderer.blank.size_bytes);
	return status;
}

// The shadow's vertex layout (location 0, a position) and its quad: two triangles over the unit square round the
// origin on the ground, placed and scaled as each shadow is drawn.
static NTSTATUS make_shadow_quad(void)
{
	const XsdkVertexElement position = { .usage = XSDK_USAGE_POSITION, .format = XSDK_VERTEX_FLOAT3 };
	NTSTATUS status = xsdk_shader_set_vertex_layout(
		&renderer.shadow_vertex_shader, &position, 1, (const uint32_t[]){ SHADOW_STRIDE_BYTES });
	if (!NT_SUCCESS(status))
		return status;
	static const float corners[SHADOW_VERTICES][3] = { { -1, 0, 1 }, { 1, 0, 1 }, { 1, 0, -1 }, { -1, 0, 1 },
		{ 1, 0, -1 }, { -1, 0, -1 } };
	renderer.shadow_quad = xsdk_gpu_alloc(sizeof corners);
	if (!renderer.shadow_quad)
		return STATUS_NO_MEMORY;
	for (uint32_t v = 0; v < SHADOW_VERTICES; v++)
		for (uint32_t c = 0; c < 3; c++)
			store_float(renderer.shadow_quad + 3 * v + c, corners[v][c]);
	xsdk_gpu_invalidate(xsdk_gpu_address(renderer.shadow_quad), sizeof corners);
	return status;
}

int avatar_render_open(void)
{
	if (renderer.opened)
		return XSDK_AVATAR_OK;
	if (!load(&renderer.vertex_shader, &avatar_vertex) || !load(&renderer.item_shader, &avatar_item_pixel) ||
		!load(&renderer.head_shader, &avatar_head_pixel) ||
		!load(&renderer.shadow_vertex_shader, &avatar_shadow_vertex) ||
		!load(&renderer.shadow_pixel_shader, &avatar_shadow_pixel)) {
		avatar_render_close();
		return XSDK_AVATAR_ERROR_GPU;
	}
	NTSTATUS status = set_layout();
	if (NT_SUCCESS(status))
		status = make_blank();
	if (NT_SUCCESS(status))
		status = make_shadow_quad();
	if (!NT_SUCCESS(status)) {
		xsdk_log_write("avatar: draw setup failed: 0x%08X", (unsigned)status);
		avatar_render_close();
		return XSDK_AVATAR_ERROR_GPU;
	}
	make_states();
	if (!renderer.light_set)
		xsdk_avatar_set_light(&default_light);
	renderer.opened = true;
	return XSDK_AVATAR_OK;
}

void avatar_render_close(void)
{
	XsdkShader *const shaders[] = { &renderer.head_shader, &renderer.item_shader, &renderer.vertex_shader,
		&renderer.shadow_pixel_shader, &renderer.shadow_vertex_shader };
	for (uint32_t s = 0; s < sizeof shaders / sizeof shaders[0]; s++)
		if (shaders[s]->microcode)
			xsdk_shader_free(shaders[s]);
	if (renderer.blank.address)
		xsdk_texture_free(&renderer.blank);
	memset(&renderer.blank, 0, sizeof renderer.blank);
	if (renderer.shadow_quad)
		xsdk_gpu_free(renderer.shadow_quad);
	renderer.shadow_quad = NULL;
	renderer.opened = false;
}

void xsdk_avatar_default_light(XsdkAvatarLight *out)
{
	*out = default_light;
}

void xsdk_avatar_set_light(const XsdkAvatarLight *in)
{
	float(*light)[4] = renderer.light;
	const float *d = in->direction;
	float length = avatar_dot3(d, d);
	length = length > 0.0f ? 1.0f / sqrtf(length) : 0.0f;
	for (uint32_t k = 0; k < 3; k++) {
		light[0][k] = d[k] * length;
		light[1][k] = in->color[k];
		light[2][k] = in->sky[k];
		light[3][k] = in->ground[k];
	}
	light[0][3] = in->wrap;
	light[1][3] = in->highlight;
	renderer.light_set = true;
}

// a less its part along unit, normalised; unchanged if that leaves nothing.
static void orthonormal(float *a, const float *unit)
{
	const float along = unit ? avatar_dot3(a, unit) : 0.0f;
	float out[3], length = 0.0f;
	for (uint32_t k = 0; k < 3; k++) {
		out[k] = a[k] - along * (unit ? unit[k] : 0.0f);
		length += out[k] * out[k];
	}
	if (length < 1e-12f)
		return;
	length = 1.0f / sqrtf(length);
	for (uint32_t k = 0; k < 3; k++)
		a[k] = out[k] * length;
}

// The camera's right, up and forward axes in world space, from a view-projection's rows: x and y in clip space grow
// along right and up, and w (the depth in a perspective) along forward; an orthographic one's z row stands in for w.
static void view_axes(const float vp[16], float axes[3][4])
{
	float rows[4][3];
	for (uint32_t r = 0; r < 4; r++)
		for (uint32_t c = 0; c < 3; c++)
			rows[r][c] = vp[4 * c + r];
	float *right = axes[0], *up = axes[1], *forward = axes[2];
	memcpy(forward, avatar_dot3(rows[3], rows[3]) > 1e-12f ? rows[3] : rows[2], 3 * sizeof(float));
	orthonormal(forward, NULL);
	memcpy(up, rows[1], 3 * sizeof(float));
	orthonormal(up, forward);
	memcpy(right, rows[0], 3 * sizeof(float));
	orthonormal(right, forward);
	orthonormal(right, up);
	right[3] = up[3] = forward[3] = 0.0f;
}

static uint32_t gpu_format(const XsdkAvatarTexture *source)
{
	return source->format == XSDK_AVATAR_TEXTURE_DXT1 ? XSDK_FORMAT_DXT1 : XSDK_FORMAT_DXT5;
}

// The bytes from one row of DXT blocks to the next, as the texture stores them.
static uint32_t block_row_bytes(const XsdkAvatarTexture *source)
{
	return source->frame_bytes / (source->height / DXT_BLOCK_ROWS);
}

// What one part's draws are built from: the drawable they go into, the part, the part's textures uploaded so far (by
// texture index), whether its face layers are, its triangles other parts hide (numbered across its meshes), and
// where the indices are put together.
typedef struct {
	AvatarDrawable *d;
	const AvatarPart *part;
	XsdkTexture *uploaded[UPLOADED_MAX];
	bool face_uploaded;
	const uint8_t *hidden;
	uint16_t *staging;
} PartBuild;

// Frame 0 of a decoded texture into GPU memory: DXT blocks as stored, whose 8-in-16 endian mode xsdk's DXT formats
// set (FORMATS.md, section 3.4).
static bool upload(AvatarDrawable *d, XsdkTexture *texture, const XsdkAvatarTexture *source)
{
	const NTSTATUS status = xsdk_texture_create(texture, gpu_format(source), source->width, source->height, 1, false);
	if (!NT_SUCCESS(status)) {
		xsdk_log_write("avatar: texture %ux%u: 0x%08X", (unsigned)source->width, (unsigned)source->height,
			(unsigned)status);
		return false;
	}
	xsdk_texture_upload(texture, 0, source->data, block_row_bytes(source));
	xsdk_gpu_invalidate(texture->address, texture->size_bytes);
	d->gpu_bytes += pages(texture->size_bytes);
	return true;
}

// The texture a binding names, uploaded once per model texture, or the blank one.
static const XsdkTexture *bound(PartBuild *b, const XsdkAvatarParameter *p)
{
	const XsdkAvatarModel *model = &b->part->model;
	if (!p || !p->is_texture || p->texture >= model->texture_count || p->texture >= UPLOADED_MAX ||
		!model->textures[p->texture].data)
		return &renderer.blank;
	if (!b->uploaded[p->texture]) {
		XsdkTexture *t = &b->d->textures[b->d->texture_count];
		if (!upload(b->d, t, &model->textures[p->texture]))
			return &renderer.blank;
		b->d->texture_count++;
		b->uploaded[p->texture] = t;
	}
	return b->uploaded[p->texture];
}

static const XsdkSamplerState *sampler_of(const XsdkAvatarParameter *p)
{
	return p && p->is_texture && p->address == XSDK_AVATAR_ADDRESS_CLAMP ? &renderer.clamp_sampler
																			: &renderer.sampler;
}

static uint32_t uv_of(const XsdkAvatarParameter *p)
{
	return p && p->is_texture && p->uv_set != XSDK_AVATAR_NO_UV_SET ? p->uv_set : 0;
}

static void set_color(float *out, const float *rgb)
{
	out[0] = rgb[0];
	out[1] = rgb[1];
	out[2] = rgb[2];
	out[3] = 1.0f;
}

// Every frame of a face layer into GPU memory, one after another in one allocation, a texture each (FORMATS.md,
// section 3.5): 14 for eyes and mouths, 5 for eyebrows, else 1.
static void upload_frames(AvatarDrawable *d, uint32_t layer, const XsdkAvatarTexture *source)
{
	if (d->face_frames[layer])
		return; // one Head an avatar
	XsdkTexture first;
	const NTSTATUS status = xsdk_texture_init(&first, gpu_format(source), source->width, source->height, 1, false);
	if (!NT_SUCCESS(status)) {
		xsdk_log_write("avatar: face layer %ux%u: 0x%08X", (unsigned)source->width, (unsigned)source->height,
			(unsigned)status);
		return;
	}
	const uint32_t stride_bytes = avatar_round_up(first.size_bytes, TEXTURE_ALIGN_BYTES);
	XsdkTexture *frames = avatar_calloc(source->frame_count, sizeof *frames, "an avatar draw");
	volatile uint32_t *memory = xsdk_gpu_alloc(stride_bytes * source->frame_count);
	if (!frames || !memory) {
		xsdk_log_write("avatar: out of memory for a face layer's %u frames", (unsigned)source->frame_count);
		free(frames);
		if (memory)
			xsdk_gpu_free(memory);
		return;
	}
	for (uint32_t f = 0; f < source->frame_count; f++) {
		frames[f] = first;
		xsdk_texture_attach(&frames[f], memory + f * stride_bytes / 4);
		xsdk_texture_upload(&frames[f], 0, source->data + f * source->frame_bytes, block_row_bytes(source));
	}
	xsdk_gpu_invalidate(xsdk_gpu_address(memory), stride_bytes * source->frame_count);
	d->face_frames[layer] = frames;
	d->face_memory[layer] = memory;
	d->face_frame_count[layer] = source->frame_count;
	d->gpu_bytes += pages(stride_bytes * source->frame_count);
	d->cpu_bytes += source->frame_count * (uint32_t)sizeof *frames;
}

// Which half of the face a Head material draws: its meshes' side of x = 0, +x the avatar's left (FORMATS.md, 4.4).
static uint32_t side_of(const XsdkAvatarModel *model, uint32_t material)
{
	float sum = 0.0f;
	for (uint32_t m = 0; m < model->mesh_count; m++)
		if (model->meshes[m].material == material)
			for (uint32_t i = 0; i < model->meshes[m].vertex_count; i++)
				sum += model->meshes[m].positions[3 * i];
	return sum >= 0.0f ? 0 : 1;
}

// The Head's draws: slot k samples with the UV set its binding names (FORMATS.md, section 3.6), from the face layers,
// uploaded once for both its halves; draws pick the frames.
static void setup_head(PartBuild *b, AvatarDraw *draw, uint32_t material, uint32_t *uv_sets)
{
	const AvatarPart *part = b->part;
	const XsdkAvatarMaterial *m = &part->model.materials[material];
	if (!b->face_uploaded) {
		for (uint32_t k = 0; k < AVATAR_HEAD_LAYERS; k++)
			if (part->layers[k].data && part->layers[k].frame_count)
				upload_frames(b->d, k, &part->layers[k]);
		b->face_uploaded = true;
	}
	draw->side = side_of(&part->model, material);
	draw->texture_count = AVATAR_HEAD_LAYERS;
	for (uint32_t k = 0; k < AVATAR_HEAD_LAYERS; k++) {
		draw->samplers[k] = &renderer.sampler;
		for (uint32_t i = 0; i < m->parameter_count; i++)
			if (m->parameters[i].is_texture && m->parameters[i].texture == k) {
				uv_sets[k] = uv_of(&m->parameters[i]);
				draw->samplers[k] = sampler_of(&m->parameters[i]);
			}
		draw->textures[k] = b->d->face_frame_count[k] ? &b->d->face_frames[k][0] : &renderer.blank;
	}
	set_color(draw->constants[HEAD_SKIN], part->skin);
	for (uint32_t k = 0; k < AVATAR_HEAD_LAYERS; k++)
		for (uint32_t c = 0; c < 3; c++)
			set_color(draw->constants[HEAD_LAYER_COLORS + 3 * k + c], part->layer_colors[k][c]);
	draw->constant_count = HEAD_CONSTANTS;
}

// An item's draws: the base, mask (if tinted) and decal textures, a reflection map in the decal's slot where there is
// no decal, the part's three colours, and whether it reflects and how much it shines.
static void setup_item(PartBuild *b, AvatarDraw *draw, uint32_t material, uint32_t *uv_sets)
{
	const AvatarPart *part = b->part;
	const XsdkAvatarMaterial *m = &part->model.materials[material];
	const XsdkAvatarParameter *base = xsdk_avatar_material_parameter(m, XSDK_AVATAR_PARAMETER_BASE);
	const XsdkAvatarParameter *mask = xsdk_avatar_material_parameter(m, XSDK_AVATAR_PARAMETER_MASK);
	const XsdkAvatarParameter *decal = xsdk_avatar_material_parameter(m, XSDK_AVATAR_PARAMETER_DECAL);
	const XsdkAvatarParameter *reflection = xsdk_avatar_material_parameter(m, XSDK_AVATAR_PARAMETER_REFLECTION);
	const XsdkAvatarParameter *shine = xsdk_avatar_material_parameter(m, XSDK_AVATAR_PARAMETER_SHINE);
	const XsdkAvatarParameter *slots[ITEM_TEXTURES] = { base, mask, decal ? decal : reflection };
	draw->texture_count = ITEM_TEXTURES;
	for (uint32_t s = 0; s < ITEM_TEXTURES; s++) {
		draw->textures[s] = s == ITEM_MASK && !part->tinted ? &renderer.blank : bound(b, slots[s]);
		uv_sets[s] = uv_of(slots[s]);
		draw->samplers[s] = sampler_of(slots[s]);
	}
	for (uint32_t c = 0; c < 3; c++)
		set_color(draw->constants[c], part->colors[c]);
	const bool reflects = !decal && reflection;
	float *r = draw->constants[ITEM_REFLECTION];
	r[0] = reflects ? 1.0f : 0.0f;
	r[1] = reflects && shine && !shine->is_texture ? shine->value[0] : 0.0f;
	r[2] = r[3] = 0.0f;
	draw->constant_count = ITEM_CONSTANTS;
}

// The textures, the texture coordinate sets for the vertex slots, and the pixel constants of one material of a part.
static void setup_draw(PartBuild *b, AvatarDraw *draw, uint32_t material, uint32_t uv_sets[UV_SLOTS])
{
	memset(uv_sets, 0, sizeof(uint32_t) * UV_SLOTS);
	draw->is_head = b->part->is_head;
	draw->see_through = b->part->model.materials[material].technique == XSDK_AVATAR_TECHNIQUE_SEE_THROUGH;
	if (b->part->is_head)
		setup_head(b, draw, material, uv_sets);
	else
		setup_item(b, draw, material, uv_sets);
}

// One vertex into GPU memory: position, normal, the texture coordinate set of each slot, the bones and weights.
static void store_vertex(volatile uint32_t *v, const XsdkAvatarMesh *mesh, uint32_t i, const uint32_t *uv_sets)
{
	for (uint32_t c = 0; c < 3; c++) {
		store_float(v + POSITION_AT + c, mesh->positions[3 * i + c]);
		store_float(v + NORMAL_AT + c, mesh->normals[3 * i + c]);
	}
	for (uint32_t s = 0; s < UV_SLOTS; s++) {
		const uint32_t set = uv_sets[s] < mesh->uv_sets ? uv_sets[s] : 0;
		const float *uv = mesh->uv_sets ? mesh->uvs + 2 * (mesh->uv_sets * i + set) : NULL;
		store_float(v + UVS_AT + 2 * s, uv ? uv[0] : 0.0f);
		store_float(v + UVS_AT + 2 * s + 1, uv ? uv[1] : 0.0f);
	}
	// Bones as the first of their three matrix rows; a mesh naming none follows the root.
	for (uint32_t k = 0; k < 4; k++) {
		uint32_t bone = mesh->bones ? mesh->bones[4 * i + k] : 0;
		if (bone >= XSDK_AVATAR_BONES)
			bone = 0;
		const float weight = mesh->weights ? (float)mesh->weights[4 * i + k] / 255.0f : (k ? 0.0f : 1.0f);
		store_float(v + BONES_AT + k, (float)(3 * bone));
		store_float(v + WEIGHTS_AT + k, weight);
	}
}

// One material's meshes of a part: their vertices, and indices of the draw's own vertices from 0, leaving out the
// triangles other parts hide.
static void fill_draw(PartBuild *b, AvatarDraw *draw, uint32_t material, const uint32_t *uv_sets)
{
	const XsdkAvatarModel *model = &b->part->model;
	uint32_t base = 0, triangle = 0;
	for (uint32_t m = 0; m < model->mesh_count; m++) {
		const XsdkAvatarMesh *mesh = &model->meshes[m];
		if (mesh->material != material) {
			triangle += mesh->index_count / 3;
			continue;
		}
		for (uint32_t i = 0; i < mesh->vertex_count; i++)
			store_vertex(b->d->vertices + (size_t)(draw->vertex_start + base + i) * VERTEX_FLOATS, mesh, i, uv_sets);
		for (uint32_t t = 0; t < mesh->index_count / 3; t++, triangle++) {
			if (b->hidden[triangle])
				continue;
			for (uint32_t c = 0; c < 3; c++)
				b->staging[draw->index_start + draw->index_count + c] = (uint16_t)(base + mesh->indices[3 * t + c]);
			draw->index_count += 3;
		}
		base += mesh->vertex_count;
	}
	draw->vertex_count = base;
}

// What the outfit needs: vertices, indices (with room to start each draw's on a word), textures and draws.
static int count_outfit(const AvatarOutfit *outfit, uint32_t *vertices, uint32_t *indices, uint32_t *textures)
{
	uint32_t draws = 0;
	*vertices = *indices = *textures = 0;
	for (uint32_t p = 0; p < outfit->part_count; p++) {
		const XsdkAvatarModel *model = &outfit->parts[p].model;
		uint32_t part_vertices = 0;
		for (uint32_t m = 0; m < model->mesh_count; m++) {
			part_vertices += model->meshes[m].vertex_count;
			*indices += model->meshes[m].index_count;
		}
		if (part_vertices > MAX_PART_VERTICES)
			return XSDK_AVATAR_ERROR_UNSUPPORTED;
		*vertices += part_vertices;
		*indices += model->material_count;
		*textures += model->texture_count + AVATAR_HEAD_LAYERS;
		draws += model->material_count;
	}
	if (draws > AVATAR_MAX_DRAWS) {
		xsdk_log_write("avatar: %u materials, more than %u", (unsigned)draws, (unsigned)AVATAR_MAX_DRAWS);
		return XSDK_AVATAR_ERROR_UNSUPPORTED;
	}
	return XSDK_AVATAR_OK;
}

// One part's draws, a draw per material, its triangles hidden by other parts left out. *vertex_at and *index_at are
// where the next draw's vertices and indices start; each draw's indices start on a word.
static int fill_part(AvatarDrawable *d, const AvatarOutfit *outfit, const AvatarPart *part, uint16_t *staging,
	uint32_t *vertex_at, uint32_t *index_at)
{
	const XsdkAvatarModel *model = &part->model;
	uint32_t triangles = 0;
	for (uint32_t m = 0; m < model->mesh_count; m++)
		triangles += model->meshes[m].index_count / 3;
	uint8_t *hidden = avatar_malloc(triangles ? triangles : 1, "an avatar draw");
	if (!hidden)
		return XSDK_AVATAR_ERROR_MEMORY;
	avatar_outfit_hidden(outfit, part, hidden, triangles);
	PartBuild b = { .d = d, .part = part, .hidden = hidden, .staging = staging };
	for (uint32_t k = 0; k < model->material_count; k++) {
		AvatarDraw *draw = &d->draws[d->draw_count++];
		uint32_t uv_sets[UV_SLOTS];
		setup_draw(&b, draw, k, uv_sets);
		draw->vertex_start = *vertex_at;
		draw->index_start = *index_at;
		fill_draw(&b, draw, k, uv_sets);
		*vertex_at += draw->vertex_count;
		*index_at += draw->index_count + (draw->index_count & 1);
	}
	free(hidden);
	return XSDK_AVATAR_OK;
}

// The staged indices into GPU memory: 16-bit, big-endian, two to a word (xsdk_gpu_draw_indexed), written a word at a
// time because the memory is write-combined.
static void write_indices(volatile uint32_t *indices, const uint16_t *staging, uint32_t count)
{
	for (uint32_t w = 0; w < (count + 1) / 2; w++)
		indices[w] = (uint32_t)staging[2 * w] << 16 | staging[2 * w + 1];
}

int avatar_render_build(AvatarDrawable *d, const AvatarOutfit *outfit)
{
	memset(d, 0, sizeof *d);
	uint32_t vertices, indices, textures;
	int result = count_outfit(outfit, &vertices, &indices, &textures);
	if (result != XSDK_AVATAR_OK)
		return result;
	const uint32_t index_bytes = (indices + 1) / 2 * 4;
	d->vertices = xsdk_gpu_alloc(vertices * STRIDE_BYTES);
	d->indices = xsdk_gpu_alloc(index_bytes);
	d->textures = avatar_calloc(textures ? textures : 1, sizeof(XsdkTexture), "an avatar draw");
	d->cpu_bytes = (textures ? textures : 1) * (uint32_t)sizeof(XsdkTexture);
	// Indices are put together here and written to GPU memory a word at a time: it is write-combined, slow to read.
	uint16_t *staging = avatar_calloc(indices + 1, sizeof(uint16_t), "an avatar draw");
	if (!d->vertices || !d->indices || !d->textures || !staging) {
		xsdk_log_write("avatar: out of memory for %u vertices, %u indices", (unsigned)vertices, (unsigned)indices);
		result = XSDK_AVATAR_ERROR_MEMORY;
		goto fail;
	}
	d->gpu_bytes += pages(vertices * STRIDE_BYTES) + pages(index_bytes);
	uint32_t vertex_at = 0, index_at = 0;
	for (uint32_t p = 0; p < outfit->part_count; p++)
		if ((result = fill_part(d, outfit, &outfit->parts[p], staging, &vertex_at, &index_at)) != XSDK_AVATAR_OK)
			goto fail;
	write_indices(d->indices, staging, index_at);
	free(staging);
	__asm__ volatile("sync" ::: "memory");
	xsdk_gpu_invalidate(xsdk_gpu_address(d->vertices), vertices * STRIDE_BYTES);
	xsdk_gpu_invalidate(xsdk_gpu_address(d->indices), (index_at + 1) / 2 * 4);
	return XSDK_AVATAR_OK;
fail:
	free(staging);
	avatar_render_free(d);
	return result;
}

static void write_literals(const AvatarShaderCode *code, bool vertex)
{
	for (uint32_t i = 0; i < code->literal_count; i++) {
		if (vertex)
			xsdk_gpu_set_vertex_constants(code->literals[i].reg, code->literals[i].values, 1);
		else
			xsdk_gpu_set_pixel_constants(code->literals[i].reg, code->literals[i].values, 1);
	}
}

// The texture a draw's slot t shows: for the Head's layers, the frame the face picks for its half.
static const XsdkTexture *texture_of(
	const AvatarDrawable *d, const AvatarDraw *draw, uint32_t t, const AvatarFaceFrames *face)
{
	if (!draw->is_head || !d->face_frame_count[t])
		return draw->textures[t];
	uint32_t frame = (*face)[draw->side][t];
	if (frame >= d->face_frame_count[t])
		frame = d->face_frame_count[t] - 1;
	return &d->face_frames[t][frame];
}

// The constants a draw's shaders share with every draw of the same shaders: the literals, the vertex shader's push
// constants and the pixel shader's lighting.
static void set_shaders(
	const AvatarDraw *draw, const float push[VERTEX_PUSH_VECTORS][4], const float lighting[LIGHT_VECTORS][4])
{
	const XsdkShader *pixel = draw->is_head ? &renderer.head_shader : &renderer.item_shader;
	const AvatarShaderCode *code = draw->is_head ? &avatar_head_pixel : &avatar_item_pixel;
	xsdk_gpu_set_shaders(&renderer.vertex_shader, pixel);
	write_literals(&avatar_vertex, true);
	write_literals(code, false);
	xsdk_gpu_set_vertex_constants(avatar_vertex.push_register, push[0], VERTEX_PUSH_VECTORS);
	xsdk_gpu_set_pixel_constants(
		code->push_register + (draw->is_head ? HEAD_LIGHT_AT : ITEM_LIGHT_AT), lighting[0], LIGHT_VECTORS);
}

// One draw: its own constants and textures, its vertices, its indices.
static void draw_one(const AvatarDrawable *d, const AvatarDraw *draw, const AvatarFaceFrames *face)
{
	const AvatarShaderCode *code = draw->is_head ? &avatar_head_pixel : &avatar_item_pixel;
	xsdk_gpu_set_pixel_constants(code->push_register, draw->constants[0], draw->constant_count);
	for (uint32_t t = 0; t < draw->texture_count; t++)
		xsdk_gpu_set_texture(code->samplers[t], texture_of(d, draw, t, face), draw->samplers[t]);
	xsdk_gpu_set_vertices(0, xsdk_gpu_address(d->vertices) + draw->vertex_start * STRIDE_BYTES,
		draw->vertex_count * STRIDE_BYTES);
	xsdk_gpu_draw_indexed(XSDK_PRIMITIVE_TRIANGLE_LIST, xsdk_gpu_address(d->indices) + draw->index_start * 2,
		draw->index_count, false);
}

void avatar_render_draw(const AvatarDrawable *d, const float view_projection[16], const float mvp[16],
	const float world[16], const float (*skin)[12], const AvatarFaceFrames *face)
{
	static float push[VERTEX_PUSH_VECTORS][4];
	memcpy(push[MVP_AT], mvp, 16 * sizeof(float));
	memcpy(push[WORLD_AT], world, 16 * sizeof(float));
	memcpy(push[SKIN_AT], skin, MATRIX_VECTORS * 4 * sizeof(float));
	float lighting[LIGHT_VECTORS][4];
	memcpy(lighting, renderer.light, sizeof renderer.light);
	view_axes(view_projection, lighting + LIGHT_SET_VECTORS);
	bool head_shaders = false, any_shaders = false;
	// Opaque parts first, then the see-through ones blended over them by their alpha.
	for (uint32_t pass = 0; pass < 2; pass++) {
		if (pass == 1)
			xsdk_gpu_set_blend(&renderer.alpha_blend);
		for (uint32_t p = 0; p < d->draw_count; p++) {
			const AvatarDraw *draw = &d->draws[p];
			if (!draw->index_count || draw->see_through != (pass == 1))
				continue;
			if (!any_shaders || draw->is_head != head_shaders) {
				set_shaders(draw, (const float(*)[4])push, (const float(*)[4])lighting);
				head_shaders = draw->is_head;
				any_shaders = true;
			}
			draw_one(d, draw, face);
		}
	}
	xsdk_gpu_set_blend(&renderer.no_blend);
}

void avatar_render_shadow(const float view_projection[16], float x, float y, float z)
{
	float push[SHADOW_VERTEX_VECTORS][4];
	memcpy(push[0], view_projection, 16 * sizeof(float));
	const float place[4] = { x, y + shadow_lift, z, shadow_radius };
	memcpy(push[4], place, sizeof place);
	const float pixel[SHADOW_PIXEL_VECTORS][4] = { { x, 0.0f, z, shadow_radius },
		{ 0.0f, 0.0f, 0.0f, shadow_strength } };
	xsdk_gpu_set_shaders(&renderer.shadow_vertex_shader, &renderer.shadow_pixel_shader);
	write_literals(&avatar_shadow_vertex, true);
	write_literals(&avatar_shadow_pixel, false);
	xsdk_gpu_set_vertex_constants(avatar_shadow_vertex.push_register, push[0], SHADOW_VERTEX_VECTORS);
	xsdk_gpu_set_pixel_constants(avatar_shadow_pixel.push_register, pixel[0], SHADOW_PIXEL_VECTORS);
	xsdk_gpu_set_vertices(0, xsdk_gpu_address(renderer.shadow_quad), SHADOW_VERTICES * SHADOW_STRIDE_BYTES);
	xsdk_gpu_set_blend(&renderer.alpha_blend);
	xsdk_gpu_draw(XSDK_PRIMITIVE_TRIANGLE_LIST, SHADOW_VERTICES);
	xsdk_gpu_set_blend(&renderer.no_blend);
}

void avatar_render_free(AvatarDrawable *d)
{
	for (uint32_t t = 0; t < d->texture_count; t++)
		xsdk_texture_free(&d->textures[t]);
	free(d->textures);
	// The face's frames share their layer's memory: freed as one.
	for (uint32_t k = 0; k < AVATAR_HEAD_LAYERS; k++) {
		free(d->face_frames[k]);
		if (d->face_memory[k])
			xsdk_gpu_free(d->face_memory[k]);
	}
	if (d->vertices)
		xsdk_gpu_free(d->vertices);
	if (d->indices)
		xsdk_gpu_free(d->indices);
	memset(d, 0, sizeof *d);
}
